const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const { transform } = require('./filter');

const ATTR_LINE = 'README.md filter=showscape';

function git(args, cwd) {
  return execFileSync('git', args, {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  }).trim();
}

function addAttributesLine(root) {
  const file = path.join(root, '.gitattributes');
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
  if (current.split(/\r?\n/).includes(ATTR_LINE)) return;
  const sep = current === '' || current.endsWith('\n') ? '' : '\n';
  fs.writeFileSync(file, current + sep + ATTR_LINE + '\n');
}

function addPrepareScript(projectDir) {
  const file = path.join(projectDir, 'package.json');
  if (!fs.existsSync(file)) return;
  const pkg = JSON.parse(fs.readFileSync(file, 'utf8'));
  pkg.scripts = pkg.scripts || {};
  if ((pkg.scripts.prepare || '').includes('showscape')) return;
  pkg.scripts.prepare = pkg.scripts.prepare
    ? pkg.scripts.prepare + ' && showscape init'
    : 'showscape init';
  fs.writeFileSync(file, JSON.stringify(pkg, null, 2) + '\n');
}

function stripLocalReadme(root) {
  const file = path.join(root, 'README.md');
  if (!fs.existsSync(file)) return;
  const before = fs.readFileSync(file, 'utf8');
  const after = transform('smudge', before);
  if (after === before) return;
  fs.writeFileSync(file, after);
  // We changed the file behind Git's back, so tell Git to re-check it.
  // Without this, git status wrongly shows README.md as modified.
  try {
    git(['add', '--', 'README.md'], root);
  } catch (err) {
    /* not fatal */
  }
}

function init(projectDir) {
  let root;
  try {
    root = git(['rev-parse', '--show-toplevel'], projectDir);
  } catch (err) {
    return { ok: false, reason: 'not a git repo' };
  }

  // Path to our cli, relative to the repo root, forward slashes for Windows
  const cli = path.join(__dirname, '..', 'bin', 'cli.js');
  const rel = path.relative(root, cli).split(path.sep).join('/');

  git(['config', '--local', 'filter.showscape.clean', 'node "' + rel + '" clean'], root);
  git(['config', '--local', 'filter.showscape.smudge', 'node "' + rel + '" smudge'], root);

  addAttributesLine(root);
  addPrepareScript(projectDir);
  stripLocalReadme(root); // clones arrive with the banner; remove it locally

  return { ok: true };
}

module.exports = { init };
